    X["Entrada&lt;br/&gt;x"] --&gt; L1["Capa 1&lt;br/&gt;h₁"]
    L1 --&gt; L2["Capa 2&lt;br/&gt;h₂"]
    L2 --&gt; O["Predicción&lt;br/&gt;ŷ"]
    O --&gt; LOSS["Pérdida&lt;br/&gt;L(ŷ,y)"]
    Y["Objetivo&lt;br/&gt;y"] --&gt; LOSS

