    X["x"] --&gt; F1["Forward&lt;br/&gt;transforma"]
    F1 --&gt; YH["ŷ"]
    YH --&gt; E["Pérdida&lt;br/&gt;compara con y"]
    E --&gt; B1["Backward&lt;br/&gt;calcula ∂L/∂θ"]
